export function attachVideoWorkshop({getLanguage=()=> 'EN'}={}){
 const langs=['EN','HU','DE','FR','ES','IT','PT','PL'],words={title:'Video workshop|Videóműhely|Videowerkstatt|Atelier vidéo|Taller de vídeo|Laboratorio video|Oficina de vídeo|Pracownia wideo',intro:'A separate local timeline for trimming, arranging clips, sound mixing and verified picture-preserving audio work.|Külön helyi idővonal vágáshoz, klipek rendezéséhez, hangkeveréshez és ellenőrzött képmegőrző hangjavításhoz.|Lokale Zeitleiste für Schnitt, Clips, Tonmischung und geprüfte Audioarbeit ohne Videoneukodierung.|Montage local pour découpe, clips, mixage et audio avec flux vidéo vérifié.|Línea local para cortes, clips, mezcla y audio conservando vídeo verificado.|Timeline locale per tagli, clip, mix audio e audio con flusso video verificato.|Linha local para cortes, clipes, mistura e áudio com vídeo preservado e verificado.|Lokalna oś do cięcia, układania klipów, miksu audio i sprawdzonego zachowania obrazu.',open:'Open video workshop|Videóműhely megnyitása|Videowerkstatt öffnen|Ouvrir atelier vidéo|Abrir taller de vídeo|Apri laboratorio video|Abrir oficina de vídeo|Otwórz pracownię wideo',error:'Restart the updated local Studio server, then reopen this page.|Indítsd újra a frissített helyi Studiót, majd nyisd meg ezt a lapot.|Aktualisierten lokalen Server neu starten und Seite öffnen.|Redémarrez le serveur local à jour et rouvrez la page.|Reinicia el servidor local actualizado y abre de nuevo.|Riavvia il server locale aggiornato e riapri.|Reinicie o servidor local atualizado e reabra.|Uruchom ponownie zaktualizowany serwer lokalny i otwórz stronę.'};const text=key=>words[key].split('|')[Math.max(0,langs.indexOf(getLanguage()))];
 const host=document.getElementById('image-workshop')||document.getElementById('virtual-studio');if(!host)return null;const root=document.createElement('section'),title=document.createElement('h2'),intro=document.createElement('p'),button=document.createElement('button'),status=document.createElement('p');root.id='video-workshop';root.style.cssText='padding:20px;margin:18px 0;border:1px solid #496777;border-radius:16px;background:var(--panel,#142734)';button.type='button';button.id='video-workshop-launcher';root.append(title,intro,button,status);host.before(root);const refresh=()=>{title.textContent=text('title');intro.textContent=text('intro');button.textContent=text('open');};button.addEventListener('click',async()=>{try{const res=await fetch('/health');if(!(await res.json()).videoWorkshop)throw Error();window.open('/video-workshop?lang='+encodeURIComponent(langs.includes(getLanguage())?getLanguage():'EN'),'_blank','noopener');status.textContent='';}catch{status.textContent=text('error');}});document.getElementById('ui-language')?.addEventListener('change',refresh);refresh();return {refresh};
}
